    slug: 'visita-papa-coincidira-pruebas-selectividad-cataluna',
    title: 'La visita del Papa en Barcelona coincidirá con las pruebas de Selectividad en Cataluña',
    excerpt: 'El viaje apostólico del Papa León XIV a Cataluña los días 9 y 10 de junio coincide plenamente con la convocatoria ordinaria de las Pruebas de Acceso a la Universidad (PAU/Selectividad), programadas del 9 al 11 de junio. Los actos centrales —vigilia en el Estadio Olímpico Lluís Companys y Santa Misa en la Sagrada Familia con la inauguración de la Torre de Jesucristo— se solapan con el examen de miles de estudiantes catalanes.',
    content: 'El viaje apostólico del Papa León XIV a Cataluña los días 9 y 10 de junio de 2026 coincidirá íntegramente con la convocatoria ordinaria de las Pruebas de Acceso a la Universidad (PAU), conocidas como Selectividad, programadas en Cataluña del 9 al 11 de junio. La situación obliga a las autoridades educativas y a los obispos catalanes a coordinar dispositivos que faciliten la asistencia tanto a los estudiantes como a los fieles que deseen participar en los actos pastorales. El miércoles 10 de junio, jornada central de la visita en Barcelona, el Papa presidirá la Santa Misa en la Basílica de la Sagrada Familia con la inauguración y bendición de la Torre de Jesucristo (172,5 m), coincidiendo con el centenario de la muerte de Antoni Gaudí. Las autoridades educativas estudian medidas específicas de movilidad para los aspirantes a la universidad que deban desplazarse a las sedes examinadoras durante el dispositivo papal.',
    date: '2026-05-11',
